async function openDetails(id){const lite=state.funds.find(x=>x.id===id);if(!lite)return;$('#detailTitle').textContent=lite.name;$('#detailSub').textContent=`${lite.amc} • ${lite.category}`;$('#detailBody').innerHTML='<div class="loading-card">Loading full factsheet fields and plan/option records…</div>';$('#detailModal').classList.remove('hidden');const [f,variants]=await Promise.all([fullFund(id),ensureVariants()]);const vr=variants.filter(v=>v.amc===f.amc&&v.baseName===f.name);const a=analyticsFor(f);const risk=[['Standard Deviation (3Y daily, annualised)',pct(riskValue(f,'stdDev3Y'))],['Downside Deviation (3Y)',pct(a.downsideDev3Y)],['Sharpe Ratio (3Y)',fmt(riskValue(f,'sharpe3Y'),3)],['Sortino Ratio (3Y)',fmt(riskValue(f,'sortino3Y'),3)],['Maximum Drawdown (3Y)',pct(a.maxDrawdown3Y)],['Calmar Ratio (3Y)',fmt(a.calmar3Y,3)],['1Y CAGR',pct(riskValue(f,'cagr1Y'))],['3Y CAGR',pct(riskValue(f,'cagr3Y'))],['5Y CAGR',pct(riskValue(f,'cagr5Y'))],['10Y CAGR',pct(riskValue(f,'cagr10Y'))],['15Y CAGR',pct(riskValue(f,'cagr15Y'))],['Analytics date',dateFmt(a.asOf)]];const roll=y=>a[`rolling${y}Y`];const rolling=[1,3,5].map(y=>{const r=roll(y);return r?`<div class="risk-card"><span>${y}Y rolling CAGR</span><b>Avg ${pct(r.average)}</b><small>Median ${pct(r.median)} • Min ${pct(r.minimum)} • Max ${pct(r.maximum)} • Positive ${pct(r.positivePct)} • ${r.observations} obs</small></div>`:''}).join('');const deep=[['Benchmark / reference index',f.benchmark&&f.benchmark!=='Benchmark not mapped'?f.benchmark:'Awaiting verified mapping'],['Riskometer',f.riskometer||'Not available'],['Exit load',f.exitLoad||'—'],['Minimum SIP',num(f.minSip)!==null?'₹'+fmt(f.minSip,0):(f.minSip||'—')],['Fund manager(s)',Array.isArray(f.fundManagers)?f.fundManagers.join(', '):(f.fundManagers||'—')],['P/E',fmt(f.pe,2)],['P/B',fmt(f.pb,2)],['Portfolio turnover',pct(f.turnover)],['YTM',pct(f.ytm)],['Modified duration',f.modifiedDuration?fmt(f.modifiedDuration,2)+' yrs':'—'],['Average maturity',f.averageMaturity?fmt(f.averageMaturity,2)+' yrs':'—'],['Equity allocation',pct(f.equityAllocation)],['Debt allocation',pct(f.debtAllocation)],['Cash allocation',pct(f.cashAllocation)],['Alpha',num(f.alpha)!==null?fmt(f.alpha,3):'Requires verified benchmark'],['Beta',fmt(f.beta,3)],['Information ratio',fmt(f.informationRatio,3)],['Tracking error',pct(f.trackingError)],['Rating',f.rating||'—'],['Portfolio date',dateFmt(f.portfolioDate)],['Deep-data refresh',dateTime(f.deepDataAt)]];const holdings=Array.isArray(f.topHoldings)?f.topHoldings:[];const sectors=Array.isArray(f.topSectors)?f.topSectors:[];const credit=f.creditQuality&&typeof f.creditQuality==='object'?f.creditQuality:{};const managers=Array.isArray(f.managerDetails)?f.managerDetails:[];const allocationSection=`<h3 class="section-title">Asset allocation</h3>${allocationHtml(f)}<div class="status-box">For hybrid and multi-asset schemes, Equity, Debt, Cash, Commodities, REITs/InvITs and Other should total approximately 100%. Differences may reflect derivatives, rounding or unclassified instruments.</div>`;const portfolioHtml=`${holdings.length?`<h3 class="section-title">Top portfolio holdings</h3><div class="scroll-table"><table class="variant-table"><thead><tr><th>Holding</th><th>Type</th><th>Sector / rating</th><th>Weight</th></tr></thead><tbody>${holdings.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.type||'—')}</td><td>${esc(x.sector||x.creditRating||'—')}</td><td>${pct(x.weightPct)}</td></tr>`).join('')}</tbody></table></div>`:''}${sectors.length?`<h3 class="section-title">Top sector allocation</h3><div class="breakdown-chips">${sectors.map(x=>`<span class="break-chip">${esc(x.sector)} <b>${pct(x.weightPct)}</b></span>`).join('')}</div>`:''}${Object.keys(credit).length?`<h3 class="section-title">Debt credit quality</h3><div class="breakdown-chips">${Object.entries(credit).map(([k,v])=>`<span class="break-chip">${esc(k)} <b>${pct(v)}</b></span>`).join('')}</div>`:''}${managers.length?`<h3 class="section-title">Fund manager tenure</h3><div class="health-list">${managers.map(x=>`<div class="health-row"><span>${esc(x.name)}</span><span>${esc(dateFmt(x.startDate))}${num(x.tenureYears)!==null?` • ${fmt(x.tenureYears,1)} yrs`:''}</span></div>`).join('')}</div>`:''}`;$('#detailBody').innerHTML=`<div class="detail-summary">${[['AMC',f.amc],['Official AMC AUM',officialAmcAum(f)?cr(officialAmcAum(f).aum)+' • '+dateFmt(officialAmcAum(f).date):'Awaiting AMFI fundwise AUM feed'],['Category',f.category],['Scheme type',f.schemeType],['Asset class',f.asset],['Launch date',dateFmt(f.launchDate)],['Representative code',f.repCode||'—'],['Representative NAV',num(f.nav)!==null?fmt(f.nav,4):'—'],['NAV date',dateFmt(f.navDate)],[effectiveAumLabel(f),cr(effectiveAum(f))],['AUM / AAUM date',dateFmt(effectiveAumDate(f))],['Direct TER',pct(directTer(f))],['Regular TER',pct(regularTer(f))]].map(([l,v])=>`<div class="detail-tile"><span>${esc(l)}</span><b>${esc(v)}</b></div>`).join('')}</div><h3 class="section-title">Return & risk analytics</h3><div class="risk-grid">${risk.map(([l,v])=>`<div class="risk-card"><span>${esc(l)}</span><b>${esc(v)}</b><small>${sourceFresh(f)?'Daily NAV analytics':'Previous/seed value — see data status'}</small></div>`).join('')}${rolling}</div><h3 class="section-title">Portfolio / factsheet / deep fields</h3><div class="detail-summary">${deep.map(([l,v])=>`<div class="detail-tile"><span>${esc(l)}</span><b>${esc(v)}</b></div>`).join('')}</div>${allocationSection}${portfolioHtml}<div class="status-box">Blank deep fields are intentional when an applicable authoritative/structured source has not supplied them yet. They are rotated through the deep-data workflow instead of being fabricated.</div><h3 class="section-title">All plan / option records (${vr.length})</h3><div class="scroll-table"><table class="variant-table"><thead><tr><th>Plan / option</th><th>Code</th><th>Plan</th><th>Option</th><th>Status</th><th>NAV</th><th>NAV date</th><th>AAUM ₹ Cr</th><th>AAUM quarter</th><th>Min investment</th><th>ISIN</th></tr></thead><tbody>${vr.map(v=>`<tr><td>${esc(v.name)}</td><td>${esc(v.code)}</td><td>${esc(v.plan)}</td><td>${esc(v.option)}</td><td>${v.active?'Active':'Inactive'}</td><td>${fmt(v.nav,4)}</td><td>${esc(dateFmt(v.navDate))}</td><td>${fmt(v.aaum,2)}</td><td>${esc(v.aaumQuarter||'—')}</td><td>${fmt(v.minInvestment,0)}</td><td>${esc(v.isin||'—')}</td></tr>`).join('')}</tbody></table></div><div class="status-box">Analytics methodology: ${esc(state.analytics.methodology?.standardDeviation||state.meta?.methodology?.stdDev||'See Data Universe status')} • Risk-free rate ${pct((state.analytics.riskFreeRate||0)*100)}.</div>`}

function selectedFunds(){return[...state.selected].map(id=>state.funds.find(f=>f.id===id)).filter(Boolean)}
async function openCompare(){const selected=selectedFunds();if(selected.length<2)return;const full=await ensureFullFunds();const map=new Map(full.map(f=>[f.id,f]));const fs=selected.map(f=>map.get(f.id)||f);const metrics=[
['Fund basics',null],['AMC',f=>f.amc],['Category',f=>cleanCategory(f)],['Asset class',f=>f.asset],['AUM / AAUM',f=>cr(effectiveAum(f))],['AUM / AAUM date',f=>dateFmt(effectiveAumDate(f))],
['Costs',null],['Direct TER',f=>pct(directTer(f)),false],['Regular TER',f=>pct(regularTer(f)),false],
['Fund returns',null],['1Y CAGR',f=>pct(riskValue(f,'cagr1Y')),true,'cagr1Y'],['3Y CAGR',f=>pct(riskValue(f,'cagr3Y')),true,'cagr3Y'],['5Y CAGR',f=>pct(riskValue(f,'cagr5Y')),true,'cagr5Y'],['10Y CAGR',f=>pct(riskValue(f,'cagr10Y')),true,'cagr10Y'],
['Risk-adjusted analytics',null],['Standard Deviation 3Y',f=>pct(riskValue(f,'stdDev3Y')),false,'stdDev3Y'],['Sharpe 3Y',f=>fmt(riskValue(f,'sharpe3Y'),3),true,'sharpe3Y'],['Sortino 3Y',f=>fmt(riskValue(f,'sortino3Y'),3),true,'sortino3Y'],['Alpha',f=>num(f.alpha)!==null?fmt(f.alpha,3):'Awaiting verified benchmark',true,'alpha'],['Beta',f=>fmt(f.beta,3),false,'beta'],['Max Drawdown 3Y',f=>pct(analyticsFor(f).maxDrawdown3Y),true,'maxDrawdown3Y'],
['Benchmark comparison',null],['Benchmark / reference index',f=>f.benchmark&&f.benchmark!=='Benchmark not mapped'?f.benchmark:'Not mapped'],['Benchmark 1Y return',f=>pct(benchmarkFor(f).cagr1Y),true,'bench1'],['Benchmark 3Y return',f=>pct(benchmarkFor(f).cagr3Y),true,'bench3'],['Benchmark 5Y return',f=>pct(benchmarkFor(f).cagr5Y),true,'bench5'],['Excess return 3Y',f=>{const x=num(riskValue(f,'cagr3Y')),b=num(benchmarkFor(f).cagr3Y);return x!==null&&b!==null?pct(x-b):'Awaiting benchmark series'},true,'excess3'],
['Asset allocation',null],['Equity',f=>pct(allocation(f).Equity)],['Debt',f=>pct(allocation(f).Debt)],['Cash',f=>pct(allocation(f).Cash)],['Commodities',f=>pct(allocation(f).Commodities)],['REITs / InvITs',f=>pct(allocation(f).REITs)],['Other / unclassified',f=>pct(allocation(f).Other)],
['Data quality',null],['Research coverage',f=>coverageScore(f)+'%'],['Analytics date',f=>dateFmt(analyticsFor(f).asOf)],['Portfolio date',f=>dateFmt(f.portfolioDate)],['Deep-data status',f=>deepLabel(f)]
];let html=`<thead><tr><th>Metric</th>${fs.map(f=>`<th>${esc(f.name)}<div class="amc">${esc(f.amc)}</div></th>`).join('')}</tr></thead><tbody>`;for(const row of metrics){const [label,getter,higher,key]=row;if(!getter){html+=`<tr class="group-row"><td colspan="${fs.length+1}">${esc(label)}</td></tr>`;continue}const raw=fs.map(f=>{if(key==='maxDrawdown3Y')return analyticsFor(f).maxDrawdown3Y;if(key==='alpha')return f.alpha;if(key==='beta')return f.beta;if(key==='bench1')return benchmarkFor(f).cagr1Y;if(key==='bench3')return benchmarkFor(f).cagr3Y;if(key==='bench5')return benchmarkFor(f).cagr5Y;if(key==='excess3'){const x=num(riskValue(f,'cagr3Y')),b=num(benchmarkFor(f).cagr3Y);return x!==null&&b!==null?x-b:null}return key?riskValue(f,key):null});let best=null;if(higher!==undefined&&raw.some(v=>num(v)!==null)){const vals=raw.map(num).filter(v=>v!==null);best=higher?Math.max(...vals):Math.min(...vals)}html+=`<tr><td>${esc(label)}</td>${fs.map((f,i)=>`<td class="${best!==null&&num(raw[i])===best?'best':''}">${esc(getter(f))}</td>`).join('')}</tr>`}html+='</tbody>';$('#compareTable').innerHTML=html;$('#compareModal').classList.remove('hidden')}

function nfoStatus(item){const today=new Date();today.setHours(0,0,0,0);const o=item.openDate?new Date(item.openDate+'T00:00:00'):null,c=item.closeDate?new Date(item.closeDate+'T23:59:59'):null;if(o&&today<o)return'upcoming';if((!o||today>=o)&&(!c||today<=c))return'open';return'closed'}
function validNfo(x){const name=String(x?.name||'').trim(),amc=String(x?.amc||'');if(!name||!/\b(fund|etf|fof|fund of fund|omni)\b/i.test(name))return false;if(/\b(blog|why|what|how|tool|watchlist|after the nfo|clear picture|working style|actually perform|type)$|>>/i.test(name))return false;if(!x.openDate||!x.closeDate)return false;const o=new Date(x.openDate),c=new Date(x.closeDate);if(Number.isNaN(o)||Number.isNaN(c)||o>c)return false;return !/discovery lead/i.test(amc)}
function nfoItems(status=state.nfoStatus){const q=$('#nfoSearch')?.value?.trim().toLowerCase()||'';let arr=[];const verified=(state.nfos.items||[]).filter(validNfo);if(status==='watch'){arr=[...(state.nfos.watch||[]),...(state.nfos.newsWatch||[]).map(x=>({name:x.title,amc:'Market signal',category:x.productType||'News / filing signal',source:x.source,officialUrl:x.url,sourceDate:x.publishedAt,_status:'watch',confidence:'Not an investable NFO record'})),...(state.nfos.items||[]).filter(x=>!validNfo(x)).map(x=>({...x,_status:'watch',confidence:'Rejected from NFO list — incomplete or non-scheme record'}))]}else if(status==='product'){arr=(state.productWatch.items||[]).map(x=>({...x,_status:'product'}))}else{arr=verified.map(x=>({...x,_status:nfoStatus(x)}));if(status!=='all')arr=arr.filter(x=>x._status===status)}if(q)arr=arr.filter(x=>`${x.name||''} ${x.amc||''} ${x.category||''} ${x.source||''}`.toLowerCase().includes(q));return arr.sort((a,b)=>String(a.closeDate||a.openDate||'9999').localeCompare(String(b.closeDate||b.openDate||'9999')))}
function renderNfoCounts(){const all=(state.nfos.items||[]).filter(validNfo),counts={open:0,upcoming:0,closed:0};all.forEach(x=>counts[nfoStatus(x)]++);$('#nfoOpenBadge').textContent=counts.open;$('#nfoOpenCount').textContent=counts.open;$('#nfoUpcomingCount').textContent=counts.upcoming;$('#nfoClosedCount').textContent=counts.closed;$('#nfoWatchCount').textContent=(state.nfos.watch||[]).length+(state.nfos.newsWatch||[]).length+(state.nfos.items||[]).filter(x=>!validNfo(x)).length;$('#nfoProductCount').textContent=(state.productWatch.items||[]).length;$('#nfoAllCount').textContent=all.length}
function renderNfos(){const arr=nfoItems();$('#nfoGrid').innerHTML=arr.length?arr.map(x=>{const st=x._status||nfoStatus(x),label=st==='open'?'OPEN NFO':st==='upcoming'?'UPCOMING NFO':st==='closed'?'RECENTLY CLOSED':st==='watch'?'SIGNAL / NEEDS VERIFICATION':'SIF / OTHER PRODUCT';const ev=x.evidenceCount?` • ${x.evidenceCount} evidence source${x.evidenceCount===1?'':'s'}`:'';const isWatch=st==='watch';return `<article class="nfo-card ${isWatch?'signal-card':''}"><span class="nfo-status ${esc(st)}">${esc(label)}</span><h3>${esc(x.name||'Unclassified signal')}</h3><div class="amc">${esc(x.amc||'—')}</div><div class="badges"><span class="badge">${esc(x.category||x.productType||'Category not supplied')}</span><span class="badge ${String(x.confidence||'').toLowerCase().includes('official')?'good':'warn'}">${esc(x.confidence||'Source cross-check')}</span></div>${isWatch?'<div class="status-box">This is a news, filing or discovery signal—not an Open NFO. Verify an official SID/KIM and valid opening/closing dates before treating it as investable.</div>':`<div class="nfo-meta"><div><span>Opens</span><b>${esc(dateFmt(x.openDate))}</b></div><div><span>Closes</span><b>${esc(dateFmt(x.closeDate))}</b></div><div><span>Offer price</span><b>${esc(x.offerPrice||'Verify SID/KIM')}</b></div><div><span>Minimum</span><b>${esc(x.minimum||'Verify SID/KIM')}</b></div></div>`}<p class="amc">${esc(x.objective||x.note||'Refer latest official scheme document')}</p><div class="amc">Source: ${esc(x.source||'Published source')} • checked/source date ${esc(dateFmt(x.sourceDate||state.nfos.generatedAt))}${ev}</div>${x.officialUrl?`<a class="link-btn" href="${esc(x.officialUrl)}" target="_blank" rel="noopener">Open source / document</a>`:''}</article>`}).join(''):'<div class="loading-card">No verified records match this tab. Use Signals / News for unverified discoveries.</div>'}
function openNfo(){renderNfos();$('#nfoSub').textContent=`Verified NFO list refreshed ${dateTime(state.nfos.generatedAt)} • Open/Upcoming tabs require a scheme-like name and valid open/close dates • news and conflicts are separated into Signals / News`;$('#nfoModal').classList.remove('hidden')}
function renderAlertCount(){const n=(state.alerts?.items||[]).length;const b=$('#alertsBadge');if(b)b.textContent=fmt(n,0)}
function renderAlerts(){const news=(state.alerts?.items||[]),official=(state.amcWatch?.items||[]);const rows=[...official.map(x=>({...x,publishedAt:x.detectedAt,source:x.source||'Official AMC website',confidence:x.confidence||'Official AMC web discovery',_official:true})),...news];const g=$('#alertsGrid');if(!g)return;if(!rows.length){g.innerHTML='<div class="status-box">No scheme-change items are currently cached. This does not mean no AMC notice exists; check Data Universe source health and the Official AMC Watch status.</div>';return}g.innerHTML=rows.slice(0,220).map(x=>`<div class="alert-card"><div class="alert-top"><span class="alert-kind">${x._official?'OFFICIAL AMC • ':''}${esc(x.kind||'Scheme update')}</span><span>${esc(dateTime(x.publishedAt))}</span></div><h3>${esc(x.title)}</h3>${x.amc?`<p><b>AMC:</b> ${esc(x.amc)}</p>`:''}${x.effectiveDate?`<p><b>Effective:</b> ${esc(dateFmt(x.effectiveDate))}</p>`:''}<p>${esc(x.source||'Discovery source')}</p><small>${esc(x.confidence||'Verify official notice')}</small>${x.url?`<a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${x._official?'Open official AMC source':'Open discovery source'}</a>`:''}</div>`).join('')}
function openAlerts(){renderAlerts();$('#alertsModal').classList.remove('hidden')}
function renderPipeline(){if(!state.meta)return;const health=state.sourceHealth?.sources||state.meta.sourceHealth||{};const rows=Object.entries(health).sort((a,b)=>String(a[0]).localeCompare(String(b[0]))).map(([k,v])=>`<div class="health-row"><span>${esc(k)}</span><span class="${v?.ok?'ok':'bad'}">${v?.ok?'OK':v?.error?'Failed':'Pending'} ${v?.records!==undefined?`• ${v.records} records`:''}${v?.latencyMs!==undefined?` • ${v.latencyMs} ms`:''}${v?.error?` • ${esc(v.error)}`:''}</span></div>`).join('');const ac=state.analytics||{},changes=state.changes||{},pipe=state.pipeline?.items||[];const changeRows=[...(changes.newSchemeCodes||[]).slice(-12).reverse().map(x=>`<div class="health-row"><span>New scheme code</span><span class="ok">${esc(x.name||x.code||JSON.stringify(x))}</span></div>`),...(changes.nameChanges||[]).slice(-8).reverse().map(x=>`<div class="health-row"><span>Name change</span><span>${esc(x.oldName||'')} → ${esc(x.newName||'')}</span></div>`)].join('');const filingRows=pipe.slice(0,12).map(x=>`<div class="health-row"><span>${esc(dateFmt(x.date))}</span><span>${esc(x.title)} <small>• ${esc(x.status||'SEBI pipeline')}</small></span></div>`).join('');const amcRows=(state.amcWatch?.amcStatus||[]).filter(x=>!x.ok).slice(0,16).map(x=>`<div class="health-row"><span>${esc(x.amc||x.website||'AMC')}</span><span class="bad">${esc(x.error||'Website did not respond on latest watch')}</span></div>`).join('');$('#pipelineBody').innerHTML=`<div class="detail-summary"><div class="detail-tile"><span>30-min NFO / change discovery</span><b>${esc(dateTime(state.meta.discoveryRefreshAt||state.nfos.generatedAt))}</b><small>Calendar-time schedule, including weekends/holidays</small></div><div class="detail-tile"><span>Hourly universe refresh</span><b>${esc(dateTime(state.meta.fastRefreshAt||state.meta.generatedAt))}</b><small>Scheme master, NAV, TER, AUM and counts</small></div><div class="detail-tile"><span>Official AMC website watch</span><b>${esc(dateTime(state.amcWatch?.generatedAt))}</b><small>${fmt(state.amcWatch?.registeredOfficialWebsites||0,0)} official websites • ${fmt(state.amcWatch?.respondingHomepages||0,0)} responding • ${fmt(state.amcWatch?.count||0,0)} retained leads</small></div><div class="detail-tile"><span>Scheme source date</span><b>${esc(dateFmt(state.counts?.sourceDate))}</b><small>NAV date can stay on last dealing day</small></div><div class="detail-tile"><span>Daily risk analytics</span><b>${esc(dateTime(state.meta.analyticsRefreshAt||ac.generatedAt))}</b><small>${(()=>{const t=state.meta.analyticsRefreshAt||ac.generatedAt;if(!t)return 'Awaiting first workflow';const h=(Date.now()-new Date(t).getTime())/36e5;return h>36?'Refresh overdue (>36h)':'Current daily build'})()}</small></div><div class="detail-tile"><span>Deep scheme rotation</span><b>${esc(dateTime(state.meta.deepRefreshAt))}</b><small>${fmt(state.meta.deepMetricsCodes||0,0)} scheme codes cached</small></div><div class="detail-tile"><span>NFO aggregation</span><b>${esc(dateTime(state.nfos.generatedAt))}</b><small>${fmt((state.nfos.items||[]).length,0)} tracked • ${fmt((state.nfos.watch||[]).length+(state.nfos.newsWatch||[]).length,0)} watch</small></div><div class="detail-tile"><span>SEBI registered MF records</span><b>${fmt(state.registry?.registeredCount||state.meta.registeredAMCCount,0)}</b></div></div><h3 class="section-title">Source universe health</h3><div class="status-box">Official AMFI, SEBI and AMC sources have highest confidence. Structured APIs are failover/enrichment. Independent NFO sites and news feeds are coverage sentinels. Conflicts are surfaced instead of silently overwriting dates.</div><div class="health-list">${rows||'<div class="status-box">Run the GitHub refresh workflows once to populate live source-health information.</div>'}</div><h3 class="section-title">Official AMC Watch — latest failures / gaps</h3><div class="health-list">${amcRows||'<div class="status-box">No AMC homepage failures are cached, or the first AMC Watch run is still pending.</div>'}</div><h3 class="section-title">Operational discovery alerts</h3><div class="health-list">${[...(state.amcWatch?.items||[]).slice(0,5),...(state.alerts?.items||[]).slice(0,5)].map(x=>`<div class="health-row"><span>${esc(x.kind||'Scheme update')}</span><span>${esc(x.title)} <small>• ${esc(dateFmt(x.detectedAt||x.publishedAt))}</small></span></div>`).join('')||'<div class="status-box">No operational-discovery alerts cached.</div>'}</div><h3 class="section-title">Recent scheme changes</h3><div class="health-list">${changeRows||'<div class="status-box">No changes logged in the seed snapshot. The hourly workflow records new scheme codes and name changes.</div>'}</div><h3 class="section-title">SEBI filing pipeline — not Open NFOs</h3><div class="health-list">${filingRows||'<div class="status-box">Awaiting SEBI filing refresh.</div>'}</div><h3 class="section-title">Refresh model</h3><div class="status-box">The phone does not crawl external websites. GitHub Actions runs a 30-minute NFO/change-discovery layer, an hourly full-universe refresh, a 4-hour official-AMC website watch, a 4-hour rotating deep-data refresh and daily historical-NAV analytics. All run by calendar schedule, including weekends and market holidays. “Sync latest” downloads the newest validated same-origin snapshot. This keeps client latency low and prevents mobile CORS/API failures.</div><div class="status-box"><b>Administrator:</b> if you need an immediate server refresh, open <a href="https://github.com/pranavgangurde-mm9/moneymantra9-mf-research/actions" target="_blank" rel="noopener noreferrer">GitHub Actions for this repository</a> and run the relevant refresh workflow. No GitHub write token is embedded in this public app.</div>`}
function newestPublishedStamp(){const xs=[state.meta?.fastRefreshAt,state.meta?.nfoRefreshAt,state.meta?.alertRefreshAt,state.meta?.deepRefreshAt,state.meta?.analyticsRefreshAt,state.nfos?.generatedAt,state.amcWatch?.generatedAt].filter(Boolean).map(x=>new Date(x)).filter(x=>!Number.isNaN(x.getTime()));return xs.length?new Date(Math.max(...xs.map(x=>x.getTime()))).toISOString():state.meta?.generatedAt}
async function refreshPublished(){const old=newestPublishedStamp();$('#refreshBtn').disabled=true;$('#refreshBtn').textContent='Reloading…';await init(true);const now=newestPublishedStamp();$('#refreshBtn').disabled=false;$('#refreshBtn').textContent='Sync latest';if(old===now)setBanner(`No newer published snapshot yet (${dateTime(now)})`,`Reload succeeded and bypassed the browser cache. NFO/scheme-alert discovery runs every 30 minutes and the full universe runs hourly, including weekends. For an immediate server crawl, the repository owner can manually run the GitHub Action.`)}

function xmlEscape(v){return String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&apos;').replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g,'')}
