function exportRows(fs){return[['Underlying Fund','AMC','Category','Asset','Active variants','Direct Growth Code','Regular Growth Code','Other Growth Code','NAV','NAV Date','Latest AUM','AUM Date','AAUM','AAUM Quarter','Direct TER %','Regular TER %','1Y CAGR %','3Y CAGR %','5Y CAGR %','10Y CAGR %','15Y CAGR %','Standard Deviation 3Y %','Downside Deviation 3Y %','Sharpe 3Y','Sortino 3Y','Max Drawdown 3Y %','Calmar 3Y','Analytics Date','Benchmark','Riskometer','P/E','P/B','Turnover %','YTM %','Modified Duration','Average Maturity','Equity %','Debt %','Cash %','Alpha','Beta','Information Ratio','Tracking Error %','Exit Load','Minimum SIP','Fund Managers','Portfolio Date','Deep Data At'],...fs.map(f=>{const a=analyticsFor(f);return[f.name,f.amc,f.category,f.asset,f.activeVariantCount,f.directGrowthCode,f.regularGrowthCode,f.otherGrowthCode,f.nav,f.navDate,f.latestAum,f.aumDate,f.aaum,f.aaumQuarter,directTer(f),regularTer(f),riskValue(f,'cagr1Y'),riskValue(f,'cagr3Y'),riskValue(f,'cagr5Y'),riskValue(f,'cagr10Y'),riskValue(f,'cagr15Y'),riskValue(f,'stdDev3Y'),a.downsideDev3Y,riskValue(f,'sharpe3Y'),riskValue(f,'sortino3Y'),a.maxDrawdown3Y,a.calmar3Y,a.asOf,f.benchmark,f.riskometer,f.pe,f.pb,f.turnover,f.ytm,f.modifiedDuration,f.averageMaturity,f.equityAllocation,f.debtAllocation,f.cashAllocation,f.alpha,f.beta,f.informationRatio,f.trackingError,f.exitLoad,f.minSip,Array.isArray(f.fundManagers)?f.fundManagers.join('; '):f.fundManagers,f.portfolioDate,f.deepDataAt]})]}

